{"query":"internal/ui/viewer handleKeyMsg key bindings f c w v t n g s","repo_root":"/c/Users/anthoni/projects/entire/anthnel/devdesk","commit":"b301ad9e4bb7f3d1f0d558656eeb8938deda213a","tree":"143c5225bfc937f8a4288e3e5981329fff161c22","profile":"full","results":[{"rank":1,"score":92.6574,"file_path":"internal/ui/viewer/update.go","start_line":165,"end_line":196,"focus_line":165,"snippet_start_line":165,"snippet_end_line":196,"symbol_start_line":165,"symbol_end_line":196,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/ui/viewer/update.go:method:Model.handleKeyMsg","symbol_name":"handleKeyMsg","qualified_name":"Model.handleKeyMsg","signature":"func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd)","signals":["path","body","exact-symbol","symbol-name","constraint:entity","exact-code-token","graph:callers","complete-symbol"],"snippet":"func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// The prompt is a mode: it claims every key before the pane sees one, the
	// way a confirmation modal does, so a digit cannot also scroll and `esc`
	// closes the prompt rather than leaving the viewer.
	if m.gotoActive {
		return m.handleGotoKey(msg)
	}
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuildText()
		return m, cmd
	}

	switch msg.String() {
	case "esc":
		return m.goBack()
	case "f":
		m.toggleDisplay()
		return m, nil
	case "c":
		m.toggleHighlight()
